def criar_departamentos_padrao(apps, schema_editor):
    Igreja = apps.get_model('configuracao', 'Igreja')
    FundoDepartamental = apps.get_model('financeiro', 'FundoDepartamental')
    DepartamentoFinanceiro = apps.get_model('financeiro', 'DepartamentoFinanceiro')
    PoliticaDepartamentoFinanceiro = apps.get_model('financeiro', 'PoliticaDepartamentoFinanceiro')

    for igreja_id in Igreja.objects.values_list('id', flat=True).iterator():
        for codigo, nome, ordem, exige_nota, exige_envio, permite_simplificada, exige_aprovacao in DEPARTAMENTOS_PADRAO:
            fundo, _ = FundoDepartamental.objects.get_or_create(
                igreja_id=igreja_id,
                codigo=codigo,
                defaults={'nome_exibicao': nome, 'ativo': True},
            )

            departamento, _ = DepartamentoFinanceiro.objects.get_or_create(
                igreja_id=igreja_id,
                codigo_interno=codigo,
                defaults={
                    'nome_exibicao': nome,
                    'tipo_departamento': 'PADRAO',
                    'ativo': True,
                    'ordem_exibicao': ordem,
                    'fundo_departamental_id': fundo.id,
                },
            )

            if not departamento.fundo_departamental_id:
                departamento.fundo_departamental_id = fundo.id
                departamento.save(update_fields=['fundo_departamental'])

            PoliticaDepartamentoFinanceiro.objects.get_or_create(
                departamento_id=departamento.id,
                defaults={
                    'exige_nota_fiscal': exige_nota,
                    'exige_envio_contabilidade': exige_envio,
                    'permite_prestacao_local_simplificada': permite_simplificada,
                    'exige_aprovacao_para_saida': exige_aprovacao,
                },
            )


